describe('Notification Dismissal', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should dismiss a notification by clicking the close button', () => {
    // Verify notification is visible
    cy.get('[data-testid="notification-item"]').should('be.visible');
    cy.get('[data-testid="notification-title"]').should('contain', 'New Message');
    cy.get('[data-testid="notification-body"]').should('contain', 'You have a new message');
    cy.get('[data-testid="close-button"]').should('be.visible');

    // Click the close button to dismiss the notification
    cy.get('[data-testid="close-button"]').click();

    // Verify notification is no longer visible
    cy.get('[data-testid="notification-item"]').should('not.exist');
    cy.get('[data-testid="notification-list"]').should('be.visible');

    // Verify success message appears
    cy.get('[data-testid="dismissal-success-message"]').should('be.visible');
    cy.get('[data-testid="dismissal-success-message"]').should('contain', 'Notification dismissed');
  });

  it('should handle multiple notifications and dismiss only the targeted one', () => {
    // Verify multiple notifications are present
    cy.get('[data-testid="notification-item"]').should('have.length', 3);
    cy.get('[data-testid="notification-title"]').first().should('contain', 'New Message');
    cy.get('[data-testid="notification-title"]').eq(1).should('contain', 'System Update');
    cy.get('[data-testid="notification-title"]').eq(2).should('contain', 'Reminder');

    // Dismiss the first notification
    cy.get('[data-testid="notification-item"]').first().find('[data-testid="close-button"]').click();

    // Verify only the first notification is dismissed
    cy.get('[data-testid="notification-item"]').should('have.length', 2);
    cy.get('[data-testid="notification-item"]').first().should('not.exist');
    cy.get('[data-testid="notification-item"]').eq(0).should('be.visible');
    cy.get('[data-testid="notification-item"]').eq(1).should('be.visible');

    // Verify the second notification is still visible
    cy.get('[data-testid="notification-title"]').eq(1).should('contain', 'System Update');

    // Dismiss the second notification
    cy.get('[data-testid="notification-item"]').eq(1).find('[data-testid="close-button"]').click();

    // Verify only the second notification is dismissed
    cy.get('[data-testid="notification-item"]').should('have.length', 1);
    cy.get('[data-testid="notification-item"]').eq(0).should('be.visible');
    cy.get('[data-testid="notification-item"]').eq(1).should('not.exist');

    // Verify the third notification remains
    cy.get('[data-testid="notification-item"]').eq(0).should('be.visible');
    cy.get('[data-testid="notification-title"]').eq(0).should('contain', 'Reminder');
  });
});
